// App.jsx - AI Chat Integration
import { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const App = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    const response = await fetch(`${API_ENDPOINT}/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message: input,
        conversationHistory: messages
      })
    });

    const data = await response.json();
    setMessages(prev => [...prev, { role: 'assistant', content: data.response }]);
    setIsLoading(false);
  };

  return (
    <motion.div className="flex flex-col h-screen">
      <ChatMessages messages={messages} />
      <ChatInput value={input} onChange={setInput} onSend={handleSend} />
    </motion.div>
  );
};

// DetailedView.jsx - Case Study Renderer
import { useParams } from 'react-router-dom';
import { motion } from 'framer-motion';

const DetailedView = ({ caseStudy }) => {
  const renderSection = (section) => {
    switch (section.type) {
      case 'visual-comparison':
        return <BeforeAfterComparison data={section} />;
      case 'interactive-architecture':
        return <ArchitectureDiagram data={section} />;
      case 'code-showcase':
        return <CodeShowcase data={section} />;
      case 'business-report':
        return <BusinessReport data={section} />;
      case 'tech-stack':
        return <TechStackViewer data={section} />;
      default:
        return null;
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="min-h-screen bg-gray-50 dark:bg-gray-900"
    >
      <HeroSection hero={caseStudy.hero} />
      {caseStudy.sections.map(section => (
        <Section key={section.id}>
          {renderSection(section)}
        </Section>
      ))}
    </motion.div>
  );
};

